   par le comportement à la hauteur naturelle du contenu : la fenêtre peut
   ainsi s'ajuster au contenu, et une fenêtre plus petite borne le cadre. */

:root:has(.win){overflow:hidden}
/* Les fondus sont ceux du corps et de la liste, pas celui du bas du cadre. */
:root:has(.win)::after{content:none}

.win{position:fixed;inset:0;display:flex;flex-direction:column;min-height:0}
.win[data-density="compact"]{--jv-gap:4px}
/* Mesure de la hauteur naturelle (comportement, le temps d'une lecture). */
.win[data-measure]>*{flex:none!important;max-height:none!important}
/* `margin-bottom` rend le bas de la coquille (`body`, 10px) : le corps du
   document mesure exactement la hauteur naturelle. */
.win-sizer{display:block;margin:0 0 -10px}

.win-body,.win-items{overflow:hidden auto;overscroll-behavior:contain}
.win-body[data-more],.win-items[data-more]{
  -webkit-mask-image:linear-gradient(#000 calc(100% - 22px),transparent);
  mask-image:linear-gradient(#000 calc(100% - 22px),transparent);
}
.win-body{flex:1 1 auto;min-height:0;padding:0 13px 10px}

/* Entrées : filet sur toute la largeur du corps, comme `.sc-items`. */
.win-items{
  flex:none;padding:8px 13px 11px;gap:4px;
  border-top:1px solid var(--jv-edge);font-size:calc(11px * var(--jv-scale));line-height:1.45;
}
.win[data-clamped] .win-items{max-height:max(55%,calc(100% - var(--win-body-natural,0px)))}
.win[data-density="compact"] .win-items{gap:2px;padding-top:6px;padding-bottom:8px}
.win[data-density="compact"] .win-body{padding-bottom:8px}

.win-item{display:flex;align-items:baseline;gap:10px;min-width:0}
.win-main{flex:1 1 auto;min-width:0}
.win-label{color:var(--jv-text);white-space:normal;overflow-wrap:anywhere}
/* La référence garde sa largeur (au plus 45 %, comme `.sc-item-ref`) ; c'est
   le libellé qui passe à la ligne, jamais elle qui se réduit à « r… ». */
.win-ref{flex:none;max-width:45%;color:var(--jv-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

